import { collect, type Token } from './define';
import type { ThemeName } from './semantic';
import { type Tokens, tokens } from './tokens';

/** The theme `:root` carries before any `data-theme` attribute or preference applies. */
export const DEFAULT_THEME: ThemeName = 'day';

const NOTICE =
  '/* Generated by `pnpm --filter @buzzkill/ui tokens` from src/tokens/tokens.ts. Do not edit by hand. */';

/** One declaration line: a primitive carries its value, a higher layer a `var()` reference. */
export function declaration(token: Token): string {
  const value = token.ref === undefined ? token.value : `var(${token.ref.name})`;
  return `  ${token.name}: ${value};`;
}

/**
 * Renders the stylesheet of the tokens: every layer on `:root` with the default theme's colors,
 * then each other theme as a `[data-theme]` block that overrides the semantic colors. The
 * output is already in the form Prettier and Stylelint keep, so the committed file never
 * changes under the hooks.
 */
export function renderTokensCss(source: Tokens = tokens): string {
  const { color, ...shared } = source.semantic;
  const root = [
    ...collect(source.primitives),
    ...collect(shared),
    ...collect(color[DEFAULT_THEME]),
    ...collect(source.components),
  ];
  const lines = [NOTICE, '', ':root {', ...root.map(declaration), '}'];
  for (const [theme, colors] of Object.entries(color)) {
    if (theme !== DEFAULT_THEME) {
      lines.push('', `[data-theme='${theme}'] {`, ...collect(colors).map(declaration), '}');
    }
  }
  return `${lines.join('\n')}\n`;
}
